module tb_TopModule;
    logic clk;
    logic areset;
    logic bump_left;
    logic bump_right;
    logic ground;
    logic walk_left;
    logic walk_right;
    logic aaah;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .ground(ground),
        .walk_left(walk_left),
        .walk_right(walk_right),
        .aaah(aaah)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        bump_left = 0;
        bump_right = 0;
        ground = 1;

        #12;
        areset = 0;
        #10;

        // Check initial state: walking left
        if (walk_left !== 1 || walk_right !== 0 || aaah !== 0) begin
            $display("SELFTEST FAIL: Initial state after reset incorrect (walk_l=%b, walk_r=%b, aaah=%b)", walk_left, walk_right, aaah);
            $finish;
        end

        // Bump left -> should walk right
        bump_left = 1;
        #10;
        bump_left = 0;
        if (walk_left !== 0 || walk_right !== 1 || aaah !== 0) begin
            $display("SELFTEST FAIL: Bump left did not switch to walk right");
            $finish;
        end

        // Bump right -> should walk left
        bump_right = 1;
        #10;
        bump_right = 0;
        if (walk_left !== 1 || walk_right !== 0 || aaah !== 0) begin
            $display("SELFTEST FAIL: Bump right did not switch to walk left");
            $finish;
        end

        // Ground drops -> should fall (aaah) while walking left
        ground = 0;
        #10;
        if (walk_left !== 0 || walk_right !== 0 || aaah !== 1) begin
            $display("SELFTEST FAIL: Did not fall when ground=0");
            $finish;
        end

        // Bump right while falling -> should not change direction
        bump_right = 1;
        #10;
        bump_right = 0;
        if (walk_left !== 0 || walk_right !== 0 || aaah !== 1) begin
            $display("SELFTEST FAIL: Falling state corrupted by bump");
            $finish;
        end

        // Ground reappears -> should resume walking left
        ground = 1;
        #10;
        if (walk_left !== 1 || walk_right !== 0 || aaah !== 0) begin
            $display("SELFTEST FAIL: Did not resume walking left when ground reappeared");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

